import api
from api import submit
from queueing import payload
from worker import execute


def test_submit_all_mode_default():
    captured = {}

    def enqueue(job):
        captured["job"] = job
        return job

    submit("alice", enqueue)
    assert captured["job"]["owner"] == "alice"
    assert captured["job"]["mode"] == "all"


def test_submit_each_mode():
    for mode in ("all", "remote", "hybrid", "office"):
        captured = {}

        def make(mode=mode):
            def enqueue(job):
                captured["job"] = job
                return job

            return enqueue

        submit("alice", make(mode), mode=mode)
        assert captured["job"]["owner"] == "alice"
        assert captured["job"]["mode"] == mode


def test_submit_invalid_mode_raises_before_enqueue():
    calls = []

    def enqueue(job):
        calls.append(job)
        raise AssertionError("enqueue must not be called for invalid mode")

    try:
        submit("alice", enqueue, mode="bogus")
    except ValueError:
        pass
    else:
        raise AssertionError("expected ValueError")
    assert calls == []


def test_submit_invalid_mode_none_mode():
    try:
        submit("alice", lambda job: job, mode=None)
    except ValueError:
        pass
    else:
        raise AssertionError("expected ValueError")


def test_submit_owner_and_signature():
    calls = []

    def enqueue(job):
        calls.append(job)
        return job

    result = submit("owner1", enqueue)
    assert len(calls) == 1
    assert calls[0]["owner"] == "owner1"
    assert result == calls[0]


def test_worker_defaults_missing_legacy_mode_to_all():
    jobs = [{"owner": "o", "mode": "all"}]
    assert execute(jobs[0], jobs) == jobs


def test_worker_unknown_mode_is_included_everywhere():
    jobs = [
        {"owner": "u1", "mode": None},
        {"owner": "u2", "mode": "other"},
        {"owner": "u3"},
    ]
    for mode in ("all", "remote", "hybrid", "office"):
        selected = execute(None, jobs, mode=mode)
        assert selected == jobs, mode


def test_worker_input_modes_match():
    jobs = [
        {"owner": "r", "mode": "remote"},
        {"owner": "h", "mode": "hybrid"},
        {"owner": "o", "mode": "office"},
        {"owner": "x", "mode": "other"},
    ]
    by_mode = {
        "remote": [jobs[0]],
        "hybrid": [jobs[1]],
        "office": [jobs[2]],
        "all": [jobs[0], jobs[1], jobs[2], jobs[3]],
    }
    for mode, expected in by_mode.items():
        assert execute(None, jobs, mode=mode) == expected


def test_worker_preserves_order_and_objects():
    jobs = [
        {"owner": "a", "mode": None},
        {"owner": "b", "mode": "hybrid"},
        {"owner": "c", "mode": None},
    ]
    selected = execute(None, jobs, mode="office")
    assert selected == [jobs[0], jobs[2]]
    assert selected[0] is jobs[0]
    assert selected[1] is jobs[2]
    assert selected.index(jobs[0]) < selected.index(jobs[2])

